```{.r .cell-code}
# Demographics by sex
exp1_freq_data %>%
  group_by(sex) %>%
  summarize(
    n = n_distinct(id),
    mean_age = mean(age),
    sd_age = sd(age)
  ) %>%
  rename(
    demographic_sex = sex,
    demographic_n = n,
    demographic_mean_age = mean_age,
    demographic_sd_age = sd_age
  ) %>%
  gt::gt() %>%
  gt::cols_label(
